export default function DevisView({ devis }) {
    if (!devis) return <div className="bg-white p-4 rounded-xl shadow text-gray-500">Aucun devis disponible</div>;

    return (
        <div className="bg-yellow-400 text-white p-5 rounded-xl shadow">
            <h3 className="text-xl font-bold mb-2">📄 Devis du projet</h3>
            <p><b>Type de construction :</b> {devis.typeConstruction}</p>
            <p><b>Superficie :</b> {devis.superficie} m²</p>
            <p className="text-2xl font-bold mt-2">💰 {devis.coutTotal} DH</p>
        </div>
    );
}
